1	<!doctype html>
2	<html lang="pt-BR">
3	<head>
4	<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
5	<title>AutoSeguro · Nova cotação</title>
6	<style>
7	/* Mock da tela Conversas v2 — cotação guiada. Paleta e casca herdadas de docs/design/ui.css. */
8	:root{
9	  --fundo:#16012F; --superficie:#1F0A40; --superficie-2:#2A1152; --borda:#3B2068;
10	  --texto:#F2ECFF; --texto-fraco:#B9A8D9; --texto-mais-fraco:#8B79B0;
11	  --magenta:#FF00FF; --ciano:#00FFFF; --azul:#198BF5;
12	  --ok:#3DDC97; --alerta:#FFC857; --falha:#FF5C7A;
13	  --r:14px; --mono:ui-monospace,"Cascadia Mono",Consolas,monospace;
14	  --lateral:248px;
15	}
16	*{box-sizing:border-box}
17	[hidden]{display:none!important}
18	html,body{height:100%}
19	body{margin:0;background:var(--fundo);color:var(--texto);
20	     font:15px/1.5 system-ui,"Segoe UI",Roboto,sans-serif;
21	     background-image:radial-gradient(900px 500px at 15% -10%, rgba(255,0,255,.10), transparent 60%),
22	                      radial-gradient(800px 500px at 92% 0%, rgba(0,255,255,.07), transparent 55%);
23	     background-attachment:fixed}
24	a{color:var(--ciano)}
25	button{font:inherit;color:inherit}
26	:focus-visible{outline:2px solid var(--ciano);outline-offset:2px}
27	
28	/* ───── casca (igual ao mock atual) ───── */
29	.app{display:grid;grid-template-columns:var(--lateral) 1fr;height:100vh}
30	@media (max-width:860px){ .app{grid-template-columns:1fr} .lateral{display:none} }
31	.lateral{background:rgba(22,1,47,.72);border-right:1px solid var(--borda);padding:18px 14px;
32	         display:flex;flex-direction:column;gap:18px;backdrop-filter:blur(6px)}
33	.produto{display:flex;flex-direction:column;gap:3px;padding:4px 8px 0}
34	.produto b{font-size:19px;position:relative;display:inline-block;isolation:isolate}
35	.produto b::before,.produto b::after{content:attr(data-t);position:absolute;inset:0;z-index:-1}
36	.produto b::before{color:var(--magenta);transform:translate(-2px,1px)}
37	.produto b::after{color:var(--ciano);transform:translate(2px,-1px)}
38	.produto span{color:var(--texto-mais-fraco);font-size:11.5px}
39	.menu{display:flex;flex-direction:column;gap:3px}
40	.menu .grupo{color:var(--texto-mais-fraco);font-size:10.5px;text-transform:uppercase;letter-spacing:.12em;padding:12px 10px 5px}
41	.menu a{display:flex;align-items:center;gap:10px;padding:9px 11px;border-radius:10px;color:var(--texto-fraco);
42	        text-decoration:none;font-size:14px;border:1px solid transparent}
43	.menu a:hover{background:var(--superficie);color:var(--texto)}
44	.menu a[aria-current="page"]{background:var(--superficie-2);color:var(--texto);border-color:var(--borda);box-shadow:inset 2px 0 0 var(--magenta)}
45	.menu a .ic{width:18px;text-align:center}
46	.selo{margin-top:auto;background:rgba(255,255,255,.04);border:1px solid var(--borda);border-radius:12px;padding:9px 10px}
47	.selo small{color:var(--texto-mais-fraco);font-size:10.5px;line-height:1.3;display:block}
48	
49	/* ───── área principal ───── */
50	.principal{display:flex;flex-direction:column;min-width:0;height:100vh}
51	.barra{display:flex;align-items:center;gap:10px;padding:10px 20px;border-bottom:1px solid var(--borda);flex-wrap:wrap}
52	.barra h1{font-size:15px;margin:0;font-weight:600}
53	.selo-mock{font-family:var(--mono);font-size:10.5px;color:var(--alerta);border:1px dashed rgba(255,200,87,.5);
54	           border-radius:999px;padding:1px 9px}
55	.barra .dir{margin-left:auto;display:flex;gap:8px;align-items:center;flex-wrap:wrap}
56	.barra label{font-size:12px;color:var(--texto-mais-fraco)}
57	.barra select,.btn-leve{background:var(--superficie);border:1px solid var(--borda);border-radius:9px;
58	           padding:5px 9px;font-size:12.5px;color:var(--texto);cursor:pointer}
59	.btn-leve:hover{border-color:var(--texto-mais-fraco)}
60	
61	.palco{flex:1;overflow-y:auto} /* sem scroll-behavior:smooth: com ele cada mensagem nova cancela a rolagem anterior (medido no teste) */
62	.coluna{max-width:760px;margin:0 auto;padding:28px 20px 24px}
63	
64	/* ───── hero (estado inicial) ───── */
65	.hero{min-height:calc(100vh - 190px);display:flex;flex-direction:column;align-items:center;justify-content:center;
66	      text-align:center;gap:14px;padding:20px 0}
67	.hero .marca{font-family:var(--mono);font-size:11.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--texto-mais-fraco)}
68	.hero h2{font-size:clamp(28px,4.2vw,42px);line-height:1.12;margin:0;max-width:17ch;text-wrap:balance;letter-spacing:-.8px}
69	.hero h2 em{font-style:normal;background:linear-gradient(90deg,var(--magenta),var(--ciano));
70	            -webkit-background-clip:text;background-clip:text;color:transparent}
71	.hero p{margin:0;color:var(--texto-fraco);max-width:52ch;font-size:16px}
72	.cta{margin-top:10px;border:0;border-radius:14px;padding:15px 26px;font-size:16.5px;font-weight:650;cursor:pointer;
73	     color:#16012F;background:linear-gradient(90deg,#FF5CFF,#7DFFFF);
74	     box-shadow:0 10px 34px -10px rgba(255,0,255,.55);transition:transform .15s,box-shadow .15s}
75	.cta:hover{transform:translateY(-1px);box-shadow:0 14px 40px -10px rgba(0,255,255,.5)}
76	.cta small{display:block;font-size:12px;font-weight:500;opacity:.75}
77	.garantias{list-style:none;padding:0;margin:18px 0 0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;width:100%}
78	@media (max-width:640px){ .garantias{grid-template-columns:1fr} }
79	.garantias li{background:rgba(31,10,64,.7);border:1px solid var(--borda);border-radius:12px;padding:11px 12px;
80	              text-align:left;font-size:12.5px;color:var(--texto-fraco)}
81	.garantias b{display:block;color:var(--texto);font-size:13px;margin-bottom:2px}
82	.proposta{width:100%;border:1px dashed var(--borda);border-radius:12px;padding:11px 14px;text-align:left;
83	          font-size:12.5px;color:var(--texto-mais-fraco)}
84	.proposta b{color:var(--alerta);font-weight:600}
85	
86	/* ───── conversa ───── */
87	.fio{display:flex;flex-direction:column;gap:14px}
88	.msg{display:flex;gap:10px;align-items:flex-end;max-width:100%;animation:entra .22s ease-out}
89	@keyframes entra{from{opacity:.001;transform:translateY(6px)}to{opacity:1;transform:none}}
90	.avatar{width:28px;height:28px;border-radius:50%;flex:none;display:grid;place-items:center;font-size:12px;font-weight:700;
91	        color:#16012F;background:linear-gradient(135deg,var(--magenta),var(--ciano))}
92	.bolha{background:var(--superficie);border:1px solid var(--borda);border-radius:16px 16px 16px 4px;padding:10px 14px;max-width:560px}
93	.bolha .quem{display:block;font-family:var(--mono);font-size:10.5px;color:var(--texto-mais-fraco);margin-bottom:3px}
94	.msg.lead{justify-content:flex-end}
95	.msg.lead .bolha{background:rgba(255,0,255,.14);border-color:rgba(255,0,255,.35);border-radius:16px 16px 4px 16px}
96	.msg.sistema .bolha{background:transparent;border-style:dashed;color:var(--texto-fraco);font-size:13.5px}
97	.digitando{display:inline-flex;gap:4px;padding:4px 0}
98	.digitando i{width:6px;height:6px;border-radius:50%;background:var(--texto-mais-fraco);animation:pisca 1s infinite}
99	.digitando i:nth-child(2){animation-delay:.15s}.digitando i:nth-child(3){animation-delay:.3s}
100	@keyframes pisca{0%,100%{opacity:.25}50%{opacity:1}}
101	
102	/* progresso */
103	.progresso{display:flex;align-items:center;gap:10px;font-size:12px;color:var(--texto-mais-fraco);margin:0 0 18px}
104	.progresso .trilho{flex:1;height:4px;background:var(--superficie-2);border-radius:99px;overflow:hidden}
105	.progresso .trilho span{display:block;height:100%;width:0;background:linear-gradient(90deg,var(--magenta),var(--ciano));transition:width .3s}
106	
107	/* cards de plano */
108	.planos{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin:4px 0 0 38px}
109	@media (max-width:640px){ .planos{grid-template-columns:1fr;margin-left:0} }
110	.plano{background:var(--superficie);border:1px solid var(--borda);border-radius:14px;padding:14px;text-align:left;cursor:pointer;
111	       display:flex;flex-direction:column;gap:8px;transition:border-color .15s,transform .15s}
112	.plano:hover{border-color:var(--texto-mais-fraco);transform:translateY(-1px)}
113	.plano[aria-pressed="true"]{border-color:var(--ciano);box-shadow:0 0 0 1px var(--ciano) inset}
114	.plano h4{margin:0;font-size:16px}
115	.plano .franquia{font-size:12px;color:var(--texto-fraco)}
116	.plano .franquia b{font-variant-numeric:tabular-nums;color:var(--texto)}
117	.plano ul{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:3px;font-size:12.5px;color:var(--texto-fraco)}
118	.plano li::before{content:"✓ ";color:var(--ok)}
119	.plano li.extra{color:var(--texto)}
120	.plano .sub{font-size:11px;color:var(--texto-mais-fraco)}
121	
122	/* resumo e resultado */
123	.cartao{background:var(--superficie);border:1px solid var(--borda);border-radius:14px;padding:14px 16px;margin-left:38px;max-width:560px}
124	@media (max-width:640px){ .cartao{margin-left:0} }
125	.cartao dl{display:grid;grid-template-columns:auto 1fr auto;gap:6px 14px;margin:0;font-size:14px}
126	.cartao dt{color:var(--texto-mais-fraco)} .cartao dd{margin:0;font-variant-numeric:tabular-nums}
127	.cartao .alt{font-size:12px;background:none;border:0;color:var(--ciano);cursor:pointer;padding:0}
128	.preco{font-size:34px;font-weight:700;letter-spacing:-.5px;font-variant-numeric:tabular-nums;margin:2px 0}
129	.preco small{font-size:14px;font-weight:500;color:var(--texto-fraco)}
130	.chips{display:flex;flex-wrap:wrap;gap:6px;margin:8px 0}
131	.chip{border-radius:999px;padding:2px 9px;font-size:11.5px;border:1px solid var(--borda);color:var(--texto-fraco)}
132	.nota{font-size:12.5px;color:var(--texto-fraco);margin:6px 0 0}
133	.rastro{margin-top:10px;padding-top:8px;border-top:1px solid var(--borda);font-family:var(--mono);font-size:11px;color:var(--texto-mais-fraco)}
134	.rastro .ok{color:var(--ok)} .rastro .falha{color:var(--falha)}
135	.tag-exemplo{font-family:var(--mono);font-size:10px;color:var(--alerta)}
136	
137	/* ───── doca de resposta ───── */
138	.doca{border-top:1px solid var(--borda);background:rgba(22,1,47,.85);backdrop-filter:blur(6px)}
139	.doca .coluna{padding:12px 20px 16px}
140	.rapidas{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:10px}
141	.rapida{background:var(--superficie);border:1px solid var(--borda);border-radius:999px;padding:7px 14px;cursor:pointer;font-size:13.5px}
142	.rapida:hover{border-color:var(--ciano)}
143	.rapida.primaria{border-color:rgba(0,255,255,.55);color:var(--ciano)}
144	.caixa{display:flex;gap:8px;background:var(--superficie);border:1px solid var(--borda);border-radius:14px;padding:6px 6px 6px 14px;align-items:center}
145	.caixa:focus-within{border-color:var(--texto-mais-fraco)}
146	.caixa input{flex:1;background:none;border:0;color:var(--texto);font-size:15px;padding:8px 0;min-width:0;outline:none}
147	.caixa input::placeholder{color:var(--texto-mais-fraco)}
148	.enviar{border:0;border-radius:10px;padding:9px 14px;font-weight:650;cursor:pointer;color:#16012F;background:var(--ciano)}
149	.enviar:disabled{opacity:.35;cursor:not-allowed}
150	.ajuda{font-size:11.5px;color:var(--texto-mais-fraco);margin:7px 2px 0;min-height:1em}
151	.ajuda.erro{color:var(--falha)}
152	
153	/* ───── especificação (gaveta) ───── */
154	.gaveta{position:fixed;inset:0 0 0 auto;width:min(460px,100%);background:var(--superficie);border-left:1px solid var(--borda);
155	        padding:22px 22px 40px;overflow-y:auto;transform:translateX(100%);transition:transform .25s;z-index:10}
156	.gaveta.aberta{transform:none}
157	.gaveta h3{margin:0 0 4px;font-size:18px}
158	.gaveta h4{margin:18px 0 6px;font-size:12px;text-transform:uppercase;letter-spacing:.1em;color:var(--texto-mais-fraco)}
159	.gaveta ol,.gaveta ul{margin:0;padding-left:18px;font-size:13.5px;color:var(--texto-fraco);display:flex;flex-direction:column;gap:6px}
160	.gaveta b{color:var(--texto)}
161	.gaveta .fechar{float:right}
162	@media (prefers-reduced-motion:reduce){ *{animation:none!important;transition:none!important;scroll-behavior:auto!important} }
163	</style>
164	</head>
165	<body>
166	<div class="app">
167	
168	<aside class="lateral">
169	  <div class="produto"><b data-t="AutoSeguro">AutoSeguro</b><span>agente de cotação · console</span></div>
170	  <nav class="menu">
171	    <div class="grupo">Atendimento</div>
172	    <a href="#" aria-current="page"><span class="ic">💬</span> Conversas</a>
173	    <a href="#"><span class="ic">🙋</span> Fila humana</a>
174	    <div class="grupo">Observabilidade</div>
175	    <a href="#"><span class="ic">🧭</span> Rastreio</a>
176	    <a href="#"><span class="ic">📈</span> Cotações</a>
177	    <a href="#"><span class="ic">🎯</span> Avaliação</a>
178	    <div class="grupo">Configuração</div>
179	    <a href="#"><span class="ic">⚖️</span> Regras e política</a>
180	  </nav>
181	  <div class="selo"><small>desafio técnico FDE<br>mock da tela Conversas v2</small></div>
182	</aside>
183	
184	<div class="principal">
185	  <div class="barra">
186	    <h1>Conversas</h1>
187	    <span class="selo-mock">MOCK · respostas simuladas no navegador</span>
188	    <div class="dir">
189	      <label for="cenario">Simular a /quote:</label>
190	      <select id="cenario">
191	        <option value="ok">responde de primeira</option>
192	        <option value="recupera">falha 1 vez e recupera</option>
193	        <option value="fora">fora do ar (3 falhas)</option>
194	      </select>
195	      <button class="btn-leve" id="btn-reiniciar" type="button">Reiniciar</button>
196	      <button class="btn-leve" id="btn-spec" type="button">O que esperamos desta tela</button>
197	    </div>
198	  </div>
199	
200	  <main class="palco" id="palco">
201	    <div class="coluna">
202	      <section class="hero" id="hero">
203	        <div class="marca">AutoSeguro · seguro auto</div>
204	        <h2>Faça aqui sua cotação <em>gratuita</em></h2>
205	        <p>Encontre o melhor seguro para o seu carro. São cinco perguntas rápidas, e o preço sai na hora, calculado pela tabela oficial.</p>
206	        <button class="cta" id="btn-comecar" type="button">Começar minha cotação →<small>sem cadastro · sem compromisso</small></button>
207	        <ul class="garantias">
208	          <li><b>Preço de verdade</b>Só mostramos valor confirmado pelo sistema de cotação. Nada de estimativa.</li>
209	          <li><b>Nunca fica sem resposta</b>Se o sistema falhar, tentamos de novo. Se não der, um corretor assume com seus dados.</li>
210	          <li><b>Seus dados protegidos</b>CEP e dados pessoais ficam mascarados no nosso registro.</li>
211	        </ul>
212	        <div class="proposta"><b>Espaço proposto · o histórico de conversas</b><br>
213	          As ~2.500 conversas de atendimento que recebemos entram aqui como atalhos (por exemplo, as dúvidas que os leads mais fazem antes de cotar).
214	          O conteúdo só entra depois de medido no dataset. Nada aqui é inventado.</div>
215	      </section>
216	
217	      <div id="conversa" hidden>
218	        <div class="progresso" id="progresso"><span id="passo-txt">Pergunta 1 de 5</span><div class="trilho"><span id="barra"></span></div></div>
219	        <div class="fio" id="fio" aria-live="polite"></div>
220	      </div>
221	    </div>
222	  </main>
223	
224	  <div class="doca" id="doca" hidden>
225	    <div class="coluna">
226	      <div class="rapidas" id="rapidas"></div>
227	      <form class="caixa" id="form">
228	        <input id="entrada" autocomplete="off" aria-label="Sua resposta">
229	        <button class="enviar" id="enviar" type="submit">Enviar</button>
230	      </form>
231	      <p class="ajuda" id="ajuda"></p>
232	    </div>
233	  </div>
234	</div>
235	</div>
236	
237	<aside class="gaveta" id="gaveta" aria-label="O que esperamos desta tela">
238	  <button class="btn-leve fechar" id="btn-fechar" type="button">Fechar</button>
239	  <h3>O que esperamos desta tela</h3>
240	  <p style="color:var(--texto-fraco);font-size:13.5px;margin:0">A porta de entrada do lead: clicar e cotar, sem instalar nada.</p>
241	  <h4>Fluxo</h4>
242	  <ol>
243	    <li><b>CTA</b> “Começar minha cotação” abre a conversa, centralizada como num chat de IA.</li>
244	    <li><b>Cinco perguntas, uma por vez</b>, com resposta rápida por botão sempre que der: idade · ano do carro · CEP (pode pular) · plano (cards) · início da vigência.</li>
245	    <li><b>Validação na hora</b> com as regras reais da <code>/planos</code>. Idade acima de 75 ou carro com mais de 20 anos: o agente explica o motivo e oferece um corretor.</li>
246	    <li><b>Resumo</b> com “alterar” em cada linha antes de cotar.</li>
247	    <li><b>Cotação</b>: o lead vê as tentativas (1 de 3, 2 de 3). O preço só aparece com resposta 200. Se as 3 falharem, a conversa vai para um humano, sem preço inventado.</li>
248	    <li><b>A IA responde</b> depois do preço: explica o plano e aceita perguntas em texto livre.</li>
249	    <li>Cada cotação mostra o <b>id e a tentativa</b>, e o link leva ao Rastreio (o critério “dá pra rastrear?”).</li>
250	  </ol>
251	  <h4>Fora deste mock (próximos pedaços)</h4>
252	  <ul>
253	    <li>Ligar ao agente real: mesmas perguntas, mesma trilha, mesma /quote.</li>
254	    <li>A resposta da IA vinda do LLM real (hoje é um texto de exemplo).</li>
255	    <li>Os atalhos vindos do histórico de conversas.</li>
256	  </ul>
257	  <h4>Decisões em aberto (suas)</h4>
258	  <ul>
259	    <li><b>Menor de 18:</b> a tabela da /planos começa em 18 e não diz o que fazer abaixo disso. O mock bloqueia, mas a regra não está escrita.</li>
260	    <li><b>Modelo do carro:</b> a /quote só usa o ano. Perguntar o modelo também (ajuda o corretor)?</li>
261	    <li><b>“Quero contratar”</b> vai para um corretor humano? No mock, vai.</li>
262	    <li><b>O preço no mock</b> é calculado no navegador com a tabela da /planos, só para parecer real. No sistema, o preço vem sempre da /quote.</li>
263	  </ul>
264	</aside>
265	
266	<script>
267	(function(){
268	  // Tabela copiada de GET /planos (quote-service), só para o mock parecer real.
269	  const PLANOS = {
270	    essencial:{nome:"Essencial", base:119.90, franquia:4500, cob:["colisao","roubo","furto"]},
271	    completo:{nome:"Completo", base:209.90, franquia:3000, cob:["colisao","roubo","furto","terceiros","vidros"]},
272	    premium:{nome:"Premium", base:339.90, franquia:1500, cob:["colisao","roubo","furto","terceiros","vidros","carro_reserva","assistencia_24h"]}
273	  };
274	  const NOME_COB = {colisao:"Colisão",roubo:"Roubo",furto:"Furto",terceiros:"Terceiros",vidros:"Vidros",carro_reserva:"Carro reserva",assistencia_24h:"Assistência 24h"};
275	  const RAPIDO = matchMedia("(prefers-reduced-motion: reduce)").matches;
276	  const HOJE = new Date(); HOJE.setHours(0,0,0,0);
277	  const ANO_ATUAL = HOJE.getFullYear();
278	
279	  const $ = id => document.getElementById(id);
280	  const fio = $("fio"), rapidas = $("rapidas"), entrada = $("entrada"), ajuda = $("ajuda"), form = $("form");
281	  let dados = {}, passoAtual = null, voltarAoResumo = false;
282	
283	  const brl = v => v.toLocaleString("pt-BR",{style:"currency",currency:"BRL"});
284	  const dataBR = d => d.toLocaleDateString("pt-BR");
285	  const esperar = ms => new Promise(r => setTimeout(r, RAPIDO ? 0 : ms));
286	  // Rola depois do conteúdo novo entrar, sem animação: rolagem suave encadeada se cancela e para no meio.
287	  // setTimeout e não requestAnimationFrame: rAF não dispara com a aba em segundo plano (medido no teste).
288	  const rolar = () => setTimeout(() => { const p = $("palco"); p.scrollTop = p.scrollHeight; }, 30);
289	
290	  function el(tag, cls, html){ const e = document.createElement(tag); if (cls) e.className = cls; if (html != null) e.innerHTML = html; return e; }
291	
292	  function mensagemLead(texto){
293	    const m = el("div","msg lead"); m.append(el("div","bolha")); m.firstChild.textContent = texto;
294	    fio.append(m); rolar();
295	  }
296	  async function mensagemBot(html, {quem="Assistente AutoSeguro", cls=""} = {}){
297	    const m = el("div","msg bot " + cls); const av = el("div","avatar","A"); const b = el("div","bolha");
298	    b.innerHTML = '<div class="digitando"><i></i><i></i><i></i></div>';
299	    m.append(av, b); fio.append(m); rolar();
300	    await esperar(520);
301	    b.innerHTML = `<span class="quem">${quem}</span>${html}`; rolar();
302	    return m;
303	  }
304	  function anexar(no){ fio.append(no); rolar(); }
305	
306	  function doca({placeholder="", tipo="text", botoes=[], textoLivre=true, dica=""}){
307	    $("doca").hidden = false;
308	    rapidas.innerHTML = "";
309	    botoes.forEach(b => {
310	      const x = el("button","rapida" + (b.primaria ? " primaria" : ""), b.rotulo); x.type = "button";
311	      x.onclick = () => b.acao(); rapidas.append(x);
312	    });
313	    form.style.display = textoLivre ? "" : "none";
314	    entrada.type = tipo; entrada.value = ""; entrada.placeholder = placeholder;
315	    ajuda.textContent = dica; ajuda.className = "ajuda";
316	    if (textoLivre) entrada.focus();
317	    rolar(); // a doca aparecendo encolhe o palco: rola de novo para a última mensagem não ficar escondida
318	  }
319	  function erro(msg){ ajuda.textContent = msg; ajuda.className = "ajuda erro"; }
320	  function progresso(n){ $("passo-txt").textContent = n > 5 ? "Tudo pronto" : `Pergunta ${n} de 5`; $("barra").style.width = Math.min(n-1,5)/5*100 + "%"; }
321	
322	  // ───── os passos ─────
323	  const PASSOS = {
324	    async idade(){
325	      progresso(1);
326	      await mensagemBot("Para começar: <b>quantos anos você tem?</b>");
327	      doca({placeholder:"Sua idade, ex.: 35", tipo:"number", dica:"Usamos a idade para a faixa de preço."});
328	      passoAtual = v => {
329	        const n = parseInt(v,10);
330	        if (!Number.isInteger(n)) return erro("Digite só o número, ex.: 35.");
331	        if (n < 18) return erro("A cotação online atende a partir de 18 anos. (regra em aberto, veja a especificação)");
332	        mensagemLead(`${n} anos`); dados.idade = n;
333	        if (n > 75) return recusa("Idade acima do limite de aceitação (75 anos).");
334	        seguir("ano");
335	      };
336	    },
337	    async ano(){
338	      progresso(2);
339	      await mensagemBot("E o carro, <b>de que ano ele é?</b>");
340	      const anos = [0,1,2,3,4].map(i => ANO_ATUAL - i);
341	      doca({placeholder:"Ou digite o ano, ex.: 2019", tipo:"number",
342	            botoes: anos.map(a => ({rotulo:String(a), acao:() => passoAtual(String(a))})),
343	            dica:"Carros com até 20 anos de uso são aceitos."});
344	      passoAtual = v => {
345	        const n = parseInt(v,10);
346	        if (!Number.isInteger(n) || n < 1950 || n > ANO_ATUAL + 1) return erro(`Digite um ano entre 1950 e ${ANO_ATUAL + 1}.`);
347	        mensagemLead(String(n)); dados.ano = n;
348	        if (ANO_ATUAL - n > 20) return recusa("Veículo com mais de 20 anos não é aceito.");
349	        seguir("cep");
350	      };
351	    },
352	    async cep(){
353	      progresso(3);
354	      await mensagemBot("Qual o <b>CEP</b> onde o carro fica à noite? <span style='color:var(--texto-mais-fraco)'>Se preferir, pode pular.</span>");
355	      doca({placeholder:"[REDIGIDO]", botoes:[{rotulo:"Pular esta pergunta", acao:() => { mensagemLead("Prefiro não informar"); dados.cep = null; seguir("plano"); }}],
356	            dica:"O CEP entra só no cálculo e fica mascarado no nosso registro."});
357	      entrada.oninput = () => { let d = entrada.value.replace(/\D/g,"").slice(0,8); entrada.value = d.length > 5 ? d.slice(0,5) + "-" + d.slice(5) : d; };
358	      passoAtual = v => {
359	        if (!/^\d{5}-\d{3}$/.test(v)) return erro("CEP com 8 números, ex.: [REDIGIDO].");
360	        entrada.oninput = null; mensagemLead(v); dados.cep = v; seguir("plano");
361	      };
362	    },
363	    async plano(){
364	      progresso(4);
365	      await mensagemBot("Agora escolha o <b>plano</b>. Toque no card que faz mais sentido para você:");
366	      const grade = el("div","planos");
367	      Object.entries(PLANOS).forEach(([id,p], i) => {
368	        const anterior = i ? Object.values(PLANOS)[i-1].cob : [];
369	        const card = el("button","plano"); card.type = "button"; card.setAttribute("aria-pressed","false");
370	        card.innerHTML = `<h4>${p.nome}</h4>
371	          <div class="franquia">Franquia <b>${brl(p.franquia)}</b></div>
372	          <ul>${p.cob.map(c => `<li class="${anterior.includes(c) ? "" : (i ? "extra" : "")}">${NOME_COB[c]}</li>`).join("")}</ul>
373	          <div class="sub">${i ? "inclui tudo do " + Object.values(PLANOS)[i-1].nome : "o básico para proteger o carro"}</div>`;
374	        card.onclick = () => {
375	          grade.querySelectorAll(".plano").forEach(c => { c.setAttribute("aria-pressed","false"); c.disabled = true; });
376	          card.setAttribute("aria-pressed","true");
377	          mensagemLead(`Plano ${p.nome}`); dados.plano = id; seguir("inicio");
378	        };
379	        grade.append(card);
380	      });
381	      anexar(grade);
382	      doca({textoLivre:false, dica:"O preço de cada plano depende do seu perfil. Ele aparece depois do resumo."});
383	    },
384	    async inicio(){
385	      progresso(5);
386	      await mensagemBot("Por último: <b>quando o seguro deve começar?</b>");
387	      const prox = new Date(HOJE.getFullYear(), HOJE.getMonth()+1, 1);
388	      doca({placeholder:"", tipo:"date",
389	            botoes:[{rotulo:`Hoje (${dataBR(HOJE)})`, acao:() => escolherInicio(HOJE)},
390	                    {rotulo:`1º do próximo mês (${dataBR(prox)})`, acao:() => escolherInicio(prox)}],
391	            dica:"Ou escolha outra data no campo acima."});
392	      entrada.min = HOJE.toISOString().slice(0,10);
393	      passoAtual = v => { if (!v) return erro("Escolha uma data."); const [a,m,d] = v.split("-").map(Number); escolherInicio(new Date(a,m-1,d)); };
394	    },
395	    async resumo(){
396	      progresso(6);
397	      const p = PLANOS[dados.plano];
398	      await mensagemBot("Confere se está tudo certo:");
399	      const c = el("div","cartao");
400	      const linha = (rot,val,passo) => `<dt>${rot}</dt><dd>${val}</dd><dd><button class="alt" type="button" data-passo="${passo}">alterar</button></dd>`;
401	      c.innerHTML = `<dl>${linha("Idade", dados.idade + " anos","idade")}${linha("Carro", "ano " + dados.ano,"ano")}
402	        ${linha("CEP", dados.cep || "não informado","cep")}${linha("Plano", p.nome,"plano")}${linha("Início", dataBR(dados.inicio),"inicio")}</dl>`;
403	      c.querySelectorAll(".alt").forEach(b => b.onclick = () => { voltarAoResumo = true; mensagemLead("Quero alterar: " + b.previousElementSibling?.textContent); PASSOS[b.dataset.passo](); });
404	      anexar(c);
405	      doca({textoLivre:false, botoes:[{rotulo:"Cotar agora →", primaria:true, acao:cotar}]});
406	    }
407	  };
408	
409	  function escolherInicio(d){ entrada.min = ""; mensagemLead(dataBR(d)); dados.inicio = d; seguir("resumo"); }
410	  function seguir(proximo){ passoAtual = null; if (voltarAoResumo && proximo !== "resumo") { voltarAoResumo = false; proximo = "resumo"; } PASSOS[proximo](); }
411	
412	  async function recusa(motivo){
413	    passoAtual = null;
414	    await mensagemBot(`Obrigado por me contar. Infelizmente não consigo cotar online neste caso: <b>${motivo}</b><br>Um corretor pode ver outras opções para você.`);
415	    doca({textoLivre:false, botoes:[{rotulo:"Falar com um corretor", primaria:true, acao:() => handoff("regra de aceitação da /planos")}, {rotulo:"Recomeçar", acao:reiniciar}]});
416	  }
417	
418	  async function handoff(motivo){
419	    mensagemLead("Quero falar com um corretor");
420	    await mensagemBot(`Pronto, já chamei um corretor. Ele recebe tudo o que você me contou, então você não precisa repetir nada. <br><span class="tag-exemplo">motivo registrado: ${motivo}</span>`,
421	      {cls:"sistema"});
422	    doca({textoLivre:false, botoes:[{rotulo:"Fazer outra cotação", acao:reiniciar}]});
423	  }
424	
425	  // ───── cotação simulada: mostra as tentativas como o agente real faz (3 tentativas) ─────
426	  async function cotar(){
427	    mensagemLead("Cotar agora");
428	    $("doca").hidden = true;
429	    const cenario = $("cenario").value;
430	    const falhas = cenario === "ok" ? 0 : cenario === "recupera" ? 1 : 3;
431	    const status = await mensagemBot("Consultando a tabela de preços… <b>tentativa 1 de 3</b>");
432	    const b = status.querySelector(".bolha");
433	    const rastro = [];
434	    for (let t = 1; t <= 3; t++) {
435	      await esperar(1100);
436	      const id = "q_" + Math.random().toString(16).slice(2,8);
437	      if (t <= falhas) {
438	        rastro.push(`<span class="falha">✗ ${id} · tentativa ${t} · ${t === 2 ? "timeout" : "503"}</span>`);
439	        if (t < 3) { b.innerHTML = `<span class="quem">Assistente AutoSeguro</span>O sistema de cotação demorou a responder. Tentando de novo… <b>tentativa ${t+1} de 3</b>`; continue; }
440	        b.innerHTML = `<span class="quem">Assistente AutoSeguro</span>O sistema de cotação está fora do ar agora. <b>Não vou chutar um preço.</b> Um corretor continua daqui com os seus dados já preenchidos.
441	          <div class="rastro">${rastro.join("<br>")}</div>`;
442	        rolar();
443	        doca({textoLivre:false, botoes:[{rotulo:"Falar com um corretor", primaria:true, acao:() => handoff("/quote indisponível após 3 tentativas")}, {rotulo:"Tentar de novo", acao:cotar}]});
444	        return;
445	      }
446	      rastro.push(`<span class="ok">✓ ${id} · tentativa ${t} · 200</span>`);
447	      b.closest(".msg").remove();
448	      return mostrarPreco(rastro);
449	    }
450	  }
451	
452	  function precoSimulado(){
453	    const p = PLANOS[dados.plano]; let v = p.base;
454	    const i = dados.idade; v *= i <= 24 ? 1.6 : i <= 29 ? 1.25 : i <= 59 ? 1.0 : 1.4;
455	    const uso = ANO_ATUAL - dados.ano; v *= uso <= 5 ? 1.0 : uso <= 10 ? 1.15 : 1.45;
456	    if (dados.cep && ["07","08","21","26","59"].includes(dados.cep.slice(0,2))) v *= 1.3;
457	    return Number(v.toFixed(2)); // mesmo arredondamento da /quote (conferido: Completo, 35 anos, 2019 → 241,38)
458	  }
459	  function primeiraParcela(valor){
460	    const d = dados.inicio, diasNoMes = new Date(d.getFullYear(), d.getMonth()+1, 0).getDate();
461	    const cobrados = diasNoMes - d.getDate() + 1;
462	    return {cobrados, diasNoMes, valor: Number((valor*cobrados/diasNoMes).toFixed(2))};
463	  }
464	
465	  async function mostrarPreco(rastro){
466	    const p = PLANOS[dados.plano], valor = precoSimulado();
467	    const carencia = new Date(dados.inicio); carencia.setDate(carencia.getDate() + 30);
468	    await mensagemBot("Sua cotação saiu:");
469	    const c = el("div","cartao");
470	    c.innerHTML = `<div style="font-size:13px;color:var(--texto-fraco)">Plano ${p.nome}</div>
471	      <div class="preco">${brl(valor)} <small>/mês</small></div>
472	      <div style="font-size:13px;color:var(--texto-fraco)">Franquia ${brl(p.franquia)}</div>
473	      <div class="chips">${p.cob.map(x => `<span class="chip">${NOME_COB[x]}</span>`).join("")}</div>
474	      <p class="nota">Roubo e furto passam a valer em ${dataBR(carencia)} (carência de 30 dias).</p>
475	      ${dados.inicio.getDate() !== 1 ? (pp => `<p class="nota">Como começa no meio do mês, a primeira parcela é proporcional: <b>${brl(pp.valor)}</b> (${pp.cobrados} de ${pp.diasNoMes} dias). As seguintes são de ${brl(valor)}.</p>`)(primeiraParcela(valor)) : ""}
476	      <div class="rastro">${rastro.join("<br>")} · <a href="#">ver no Rastreio</a><br><span class="tag-exemplo">valor calculado no navegador (mock) · no sistema vem da /quote</span></div>`;
477	    anexar(c);
478	    const outros = Object.keys(PLANOS).filter(k => k !== dados.plano).map(k => PLANOS[k].nome);
479	    await mensagemBot(`Com ${dados.idade} anos e um carro ${dados.ano}, o <b>${p.nome}</b> fica em ${brl(valor)} por mês.
480	      ${dados.plano === "essencial" ? "Ele cobre colisão, roubo e furto. Se você quiser proteção contra danos a terceiros e vidros, o Completo inclui." : "Ele já inclui proteção para terceiros e vidros, que o Essencial não tem."}
481	      Quer tirar alguma dúvida ou comparar com o ${outros.join(" ou o ")}?<br><span class="tag-exemplo">IA · texto de exemplo. No sistema, a resposta vem do LLM real.</span>`, {quem:"IA AutoSeguro"});
482	    doca({placeholder:"Pergunte algo sobre o plano…", dica:"Resposta livre da IA: próximo pedaço.",
483	      botoes:[{rotulo:"Quero contratar", primaria:true, acao:() => handoff("lead quer contratar")},
484	              {rotulo:"Ver outro plano", acao:() => { mensagemLead("Quero ver outro plano"); voltarAoResumo = true; PASSOS.plano(); }},
485	              {rotulo:"Falar com um corretor", acao:() => handoff("lead pediu humano")}]});
486	    passoAtual = async v => { mensagemLead(v); entrada.value = ""; await mensagemBot("(Próximo pedaço: aqui a IA responde de verdade, com o LLM, sem inventar preço nem aprovar desconto.)", {quem:"IA AutoSeguro", cls:"sistema"}); };
487	  }
488	
489	  function enviar(){ const v = entrada.value.trim(); if (passoAtual && v) passoAtual(v); }
490	  form.addEventListener("submit", e => { e.preventDefault(); enviar(); });
491	  entrada.addEventListener("keydown", e => { if (e.key === "Enter") { e.preventDefault(); enviar(); } });
492	
493	  function reiniciar(){
494	    dados = {}; passoAtual = null; voltarAoResumo = false; fio.innerHTML = "";
495	    $("hero").hidden = false; $("conversa").hidden = true; $("doca").hidden = true; $("palco").scrollTop = 0;
496	  }
497	  $("btn-comecar").onclick = async () => {
498	    $("hero").hidden = true; $("conversa").hidden = false;
499	    await mensagemBot("Oi! Sou o assistente da AutoSeguro. Vou te fazer <b>5 perguntas rápidas</b> e já te mostro o preço.");
500	    PASSOS.idade();
501	  };
502	  $("btn-reiniciar").onclick = reiniciar;
503	  $("btn-spec").onclick = () => $("gaveta").classList.add("aberta");
504	  $("btn-fechar").onclick = () => $("gaveta").classList.remove("aberta");
505	})();
506	</script>
507	</body>
508	</html>
