1	<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
2	<title>AutoSeguro · Histórico de conversas</title><style>
3	:root{--fundo:#16012F;--sup:#1F0A40;--sup2:#2A1152;--borda:#3B2068;--texto:#F2ECFF;--fraco:#B9A8D9;--mais:#8B79B0;
4	--cia:#00FFFF;--ok:#3DDC97;--alerta:#FFC857;--falha:#FF5C7A;--mono:ui-monospace,Consolas,monospace}
5	*{box-sizing:border-box}[hidden]{display:none!important}
6	body{margin:0;background:var(--fundo);color:var(--texto);font:14.5px/1.5 system-ui,"Segoe UI",sans-serif}
7	main{max-width:1180px;margin:0 auto;padding:26px 22px 60px}
8	h1{margin:0 0 4px;font-size:24px} h2{font-size:13px;text-transform:uppercase;letter-spacing:.1em;color:var(--fraco);margin:26px 0 10px}
9	.sub{color:var(--fraco);margin:0 0 6px;max-width:80ch} .aviso{font-family:var(--mono);font-size:11.5px;color:var(--alerta)}
10	.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:10px;margin-top:16px}
11	.kpi{background:var(--sup);border:1px solid var(--borda);border-radius:12px;padding:11px 14px}
12	.kpi span{font-size:11px;color:var(--mais);text-transform:uppercase;letter-spacing:.08em}
13	.kpi b{display:block;font-size:22px;font-variant-numeric:tabular-nums} .kpi small{color:var(--fraco);font-size:11.5px}
14	.duas{display:grid;grid-template-columns:1fr 1fr;gap:14px} @media(max-width:900px){.duas{grid-template-columns:1fr}}
15	.tab{background:var(--sup);border:1px solid var(--borda);border-radius:12px;overflow:auto}
16	table{border-collapse:collapse;width:100%;font-size:13px}
17	td{padding:6px 10px;border-top:1px solid var(--borda);vertical-align:top}
18	td.n{font-family:var(--mono);color:var(--cia);text-align:right;white-space:nowrap;width:1%}
19	.tab h3{margin:0;padding:9px 12px;font-size:12px;color:var(--fraco);text-transform:uppercase;letter-spacing:.08em}
20	.filtros{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px}
21	.filtros button{background:var(--sup);color:var(--texto);border:1px solid var(--borda);border-radius:999px;padding:6px 13px;cursor:pointer;font:inherit;font-size:13px}
