// ───── os passos ─────
const PASSOS = {
  async idade(){
    progresso(1);
    await mensagemBot("Para começar: <b>quantos anos você tem?</b>");
    doca({placeholder:"Sua idade, ex.: 35", tipo:"number", dica:"Usamos a idade para a faixa de preço."});
    passoAtual = v => {
      const n = parseInt(v,10);
      if (!Number.isInteger(n)) return erro("Digite só o número, ex.: 35.");
      if (n < 18) return erro("A cotação online atende a partir de 18 anos. (regra em aberto, veja a especificação)");
      mensagemLead(`${n} anos`); dados.idade = n;
      if (n > 75) return recusa("Idade acima do limite de aceitação (75 anos).");
      seguir("ano");
    };
  },
  async ano(){
    progresso(2);
    await mensagemBot("E o carro, <b>de que ano ele é?</b>");
    const anos = [0,1,2,3,4].map(i => ANO_ATUAL - i);
    doca({placeholder:"Ou digite o ano, ex.: 2019", tipo:"number",
          botoes: anos.map(a => ({rotulo:String(a), acao:() => passoAtual(String(a))})),
          dica:"Carros com até 20 anos de uso são aceitos."});
    passoAtual = v => {
      const n = parseInt(v,10);
      if (!Number.isInteger(n) || n < 1950 || n > ANO_ATUAL + 1) return erro(`Digite um ano entre 1950 e ${ANO_ATUAL + 1}.`);
      mensagemLead(String(n)); dados.ano = n;
      if (ANO_ATUAL - n > 20) return recusa("Veículo com mais de 20 anos não é aceito.");
      seguir("cep");
    };
  },
  async cep(){
    progresso(3);
    await mensagemBot("Qual o <b>CEP</b> onde o carro fica à noite? <span style='color:var(--texto-mais-fraco)'>Se preferir, pode pular.</span>");
    doca({placeholder:"[REDIGIDO]", botoes:[{rotulo:"Pular esta pergunta", acao:() => { mensagemLead("Prefiro não informar"); dados.cep = null; seguir("plano"); }}],
          dica:"O CEP entra só no cálculo e fica mascarado no nosso registro."});
    entrada.oninput = () => { let d = entrada.value.replace(/\D/g,"").slice(0,8); entrada.value = d.length > 5 ? d.slice(0,5) + "-" + d.slice(5) : d; };
    passoAtual = v => {
      if (!/^\d{5}-\d{3}$/.test(v)) return erro("CEP com 8 números, ex.: [REDIGIDO].");
      entrada.oninput = null; mensagemLead(v); dados.cep = v; seguir("plano");
    };
  },
  async plano(){
    progresso(4);
    await mensagemBot("Agora escolha o <b>plano</b>. Toque no card que faz mais sentido para você:");
    const grade = el("div","planos");
    Object.entries(PLANOS).forEach(([id,p], i) => {
      const anterior = i ? Object.values(PLANOS)[i-1].cob : [];
      const card = el("button","plano"); card.type = "button"; card.setAttribute("aria-pressed","false");
      card.innerHTML = `<h4>${p.nome}</h4>
        <div class="franquia">Franquia <b>${brl(p.franquia)}</b></div>
        <ul>${p.cob.map(c => `<li class="${anterior.includes(c) ? "" : (i ? "extra" : "")}">${NOME_COB[c]}</li>`).join("")}</ul>
        <div class="sub">${i ? "inclui tudo do " + Object.values(PLANOS)[i-1].nome : "o básico para proteger o carro"}</div>`;
      card.onclick = () => {
        grade.querySelectorAll(".plano").forEach(c => { c.setAttribute("aria-pressed","false"); c.disabled = true; });
        card.setAttribute("aria-pressed","true");
        mensagemLead(`Plano ${p.nome}`); dados.plano = id; seguir("inicio");
      };
      grade.append(card);
    });
    anexar(grade);
    doca({textoLivre:false, dica:"O preço de cada plano depende do seu perfil. Ele aparece depois do resumo."});
  },
  async inicio(){
    progresso(5);
    await mensagemBot("Por último: <b>quando o seguro deve começar?</b>");
    const prox = new Date(HOJE.getFullYear(), HOJE.getMonth()+1, 1);
    doca({placeholder:"", tipo:"date",
          botoes:[{rotulo:`Hoje (${dataBR(HOJE)})`, acao:() => escolherInicio(HOJE)},
                  {rotulo:`1º do próximo mês (${dataBR(prox)})`, acao:() => escolherInicio(prox)}],
          dica:"Ou escolha outra data no campo acima."});
    entrada.min = HOJE.toISOString().slice(0,10);
    passoAtual = v => { if (!v) return erro("Escolha uma data."); const [a,m,d] = v.split("-").map(Number); escolherInicio(new Date(a,m-1,d)); };
  },
  async resumo(){
    progresso(6);
    const p = PLANOS[dados.plano];
    await mensagemBot("Confere se está tudo certo:");
    const c = el("div","cartao");
    const linha = (rot,val,passo) => `<dt>${rot}</dt><dd>${val}</dd><dd><button class="alt" type="button" data-passo="${passo}">alterar</button></dd>`;
    c.innerHTML = `<dl>${linha("Idade", dados.idade + " anos","idade")}${linha("Carro", "ano " + dados.ano,"ano")}
      ${linha("CEP", dados.cep || "não informado","cep")}${linha("Plano", p.nome,"plano")}${linha("Início", dataBR(dados.inicio),"inicio")}</dl>`;
    c.querySelectorAll(".alt").forEach(b => b.onclick = () => { voltarAoResumo = true; mensagemLead("Quero alterar: " + b.previousElementSibling?.textContent); PASSOS[b.dataset.passo](); });
    anexar(c);
    doca({textoLivre:false, botoes:[{rotulo:"Cotar agora →", primaria:true, acao:cotar}]});
  }
};

