  },
  async whatsapp(){
    progresso(2);
    await mensagemBot("Qual o seu <b>WhatsApp</b>? Escolha o país e digite o número.");
    doca({placeholder:"Número, com DDD", pais:true});
    const aplicarMascaraBR = () => {
      const d = entrada.value.replace(/\D/g,"").slice(0,11);
      if (d.length > 6) entrada.value = `(${d.slice(0,2)}) ${d.slice(2, d.length > 10 ? 7 : 6)}-${d.slice(d.length > 10 ? 7 : 6)}`;
      else if (d.length > 2) entrada.value = `(${d.slice(0,2)}) ${d.slice(2)}`;
      else entrada.value = d;
    };
    const aplicarMascaraOutro = () => { entrada.value = entrada.value.replace(/\D/g,"").slice(0,14); };
    const atualizarMascara = () => { entrada.value = ""; entrada.oninput = paisSel.value === "BR" ? aplicarMascaraBR : aplicarMascaraOutro; };
    paisSel.onchange = atualizarMascara;
    atualizarMascara();
    passoAtual = v => {
      const pais = PAISES.find(p => p.iso === paisSel.value) || PAISES[0];
      const digitos = v.replace(/\D/g,"");
      let exibicao;
      if (pais.iso === "BR") {
        if (digitos.length !== 10 && digitos.length !== 11) return erro("Digite DDD e número, ex.: (11) [REDIGIDO]8.");
        const ddd = digitos.slice(0,2), resto = digitos.slice(2);
        exibicao = `+${pais.ddi} (${ddd}) ${digitos.length === 11 ? resto.slice(0,5) + "-" + resto.slice(5) : resto.slice(0,4) + "-" + resto.slice(4)}`;
      } else {
        if (digitos.length < 4 || digitos.length > 14 || (String(pais.ddi).length + digitos.length) > 15) return erro("Digite só os números do telefone, sem o código do país.");
        exibicao = `+${pais.ddi} ${digitos}`;
      }
      mensagemLead(exibicao);
      dados.whatsapp = {iso: pais.iso, ddi: pais.ddi, numero: digitos, exibicao};
      seguir("email");
    };
  },
  async email(){
    progresso(3);
    await mensagemBot("Se quiser, deixe seu <b>e-mail</b>. É opcional.");
    doca({placeholder:"[REDIGIDO]", tipo:"email",
          botoes:[{rotulo:"Pular, não uso muito e-mail", acao:() => { mensagemLead("Prefiro não informar"); dados.email = null; seguir("idade"); }}]});
    passoAtual = v => {
      if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.trim())) return erro("Esse e-mail não parece válido. Confira ou toque em Pular.");
      mensagemLead(v.trim()); dados.email = v.trim(); seguir("idade");
    };
  },
  async idade(){
    progresso(4);
    await mensagemBot("Para começar: <b>quantos anos você tem?</b>");
    doca({placeholder:"Sua idade, ex.: 35", tipo:"number", dica:"Usamos a idade para a faixa de preço."});
    passoAtual = v => {
      const n = parseInt(v,10);
      if (!Number.isInteger(n)) return erro("Digite só o número, ex.: 35.");
      mensagemLead(`${n} anos`); dados.idade = n;
      if (n < 18) return menorDeIdade();
      if (n > 75) return recusa("Idade acima do limite de aceitação (75 anos).");
      seguir("modelo");
    };
  },
  async modelo(){
    progresso(5);
    await mensagemBot("Qual o <b>modelo</b> do seu carro? (ex.: Onix, HB20, Corolla)");
    doca({placeholder:"Modelo do carro", dica:"O modelo fica registrado para o corretor. Nesta cotação ele não altera o preço."});
    passoAtual = v => {
      const modelo = v.trim();
      if (modelo.length < 2) return erro("Digite o modelo do carro.");
      mensagemLead(modelo); dados.modelo = modelo; seguir("ano");
    };
  },
  async ano(){
    progresso(6);
    await mensagemBot(`E o seu ${dados.modelo}, <b>de que ano é?</b>`);
    const anos = [0,1,2,3,4].map(i => ANO_ATUAL - i);
    doca({placeholder:"Ou digite o ano, ex.: 2019", tipo:"number",
          botoes: anos.map(a => ({rotulo:String(a), acao:() => passoAtual(String(a))})),
          dica:"Carros com até 20 anos de uso são aceitos."});
    passoAtual = v => {
      const n = parseInt(v,10);
      if (!Number.isInteger(n) || n < 1950 || n > ANO_ATUAL + 1) return erro(`Digite um ano entre 1950 e ${ANO_ATUAL + 1}.`);
      mensagemLead(String(n)); dados.ano = n;
      if (ANO_ATUAL - n > 20) return recusa("Veículo com mais de 20 anos não é aceito.");
      seguir("cep");
    };
  },
  async cep(){
    progresso(7);
    await mensagemBot("Qual o <b>CEP</b> onde o carro fica à noite? <span style='color:var(--texto-mais-fraco)'>Se preferir, pode pular.</span>");
    doca({placeholder:"[REDIGIDO]", botoes:[{rotulo:"Pular esta pergunta", acao:() => { mensagemLead("Prefiro não informar"); dados.cep = null; seguir("plano"); }}],
          dica:"O CEP entra só no cálculo e fica mascarado no nosso registro."});
    entrada.oninput = () => { let d = entrada.value.replace(/\D/g,"").slice(0,8); entrada.value = d.length > 5 ? d.slice(0,5) + "-" + d.slice(5) : d; };
    passoAtual = v => {
      if (!/^\d{5}-\d{3}$/.test(v)) return erro("CEP com 8 números, ex.: [REDIGIDO].");
      entrada.oninput = null; mensagemLead(v); dados.cep = v; seguir("plano");
    };
  },
  async plano(){
    progresso(8);
    await mensagemBot(`Agora escolha o <b>plano</b>. Toque no card que faz mais sentido para você:
      <details><summary>O que é franquia?</summary>Franquia é o valor que você paga do seu bolso quando usa o seguro para consertar o carro depois de um dano parcial, como uma batida. O seguro paga o restante do conserto. Exemplo ilustrativo: com franquia de R$ 3.000,00, um conserto de R$ 8.000,00 fica R$ 3.000,00 para você e R$ 5.000,00 para o seguro. Quanto menor a franquia, menos você paga quando precisa usar o seguro.</details>`);
    const grade = el("div","planos");
    Object.entries(PLANOS).forEach(([id,p], i) => {
      const anterior = i ? Object.values(PLANOS)[i-1].cob : [];
      const card = el("button","plano"); card.type = "button"; card.setAttribute("aria-pressed","false");
      card.innerHTML = `<h4>${p.nome}</h4>
        <div class="franquia">Franquia <b>${brl(p.franquia)}</b></div>
        <ul>${p.cob.map(c => `<li class="${anterior.includes(c) ? "" : (i ? "extra" : "")}">${NOME_COB[c]}</li>`).join("")}</ul>
        <div class="sub">${i ? "inclui tudo do " + Object.values(PLANOS)[i-1].nome : "o básico para proteger o carro"}</div>`;
      card.onclick = () => {
        grade.querySelectorAll(".plano").forEach(c => { c.setAttribute("aria-pressed","false"); c.disabled = true; });
        card.setAttribute("aria-pressed","true");
        mensagemLead(`Plano ${p.nome}`); dados.plano = id; seguir("inicio");
      };
      grade.append(card);
    });
    anexar(grade);
    doca({textoLivre:false, dica:"O preço de cada plano depende do seu perfil. Ele aparece depois do resumo."});
  },
  async inicio(){
    progresso(9);
    await mensagemBot("Por último: <b>quando o seguro deve começar?</b>");
    const prox = new Date(HOJE.getFullYear(), HOJE.getMonth()+1, 1);
    doca({placeholder:"", tipo:"date",
          botoes:[{rotulo:`Hoje (${dataBR(HOJE)})`, acao:() => escolherInicio(HOJE)},
                  {rotulo:`1º do próximo mês (${dataBR(prox)})`, acao:() => escolherInicio(prox)}],
          dica:"Ou escolha outra data no campo acima."});
    entrada.min = HOJE.toISOString().slice(0,10);
    passoAtual = v => { if (!v) return erro("Escolha uma data."); const [a,m,d] = v.split("-").map(Number); escolherInicio(new Date(a,m-1,d)); };
  },
  async resumo(){
    progresso(10);
    const p = PLANOS[dados.plano];
    await mensagemBot("Confere se está tudo certo:");
    const c = el("div","cartao");
    const linha = (rot,val,passo) => `<dt>${rot}</dt><dd>${val}</dd><dd><button class="alt" type="button" data-passo="${passo}">alterar</button></dd>`;
    c.innerHTML = `<dl>${linha("Nome", dados.nome,"nome")}${linha("WhatsApp", dados.whatsapp.exibicao,"whatsapp")}
      ${linha("E-mail", dados.email || "não informado","email")}${linha("Idade", dados.idade + " anos","idade")}
      ${linha("Carro", dados.modelo + " " + dados.ano,"modelo")}${linha("CEP", dados.cep || "não informado","cep")}
      ${linha("Plano", p.nome,"plano")}${linha("Início", dataBR(dados.inicio),"inicio")}</dl>`;
    c.querySelectorAll(".alt").forEach(b => b.onclick = () => { voltarAoResumo = true; mensagemLead("Quero alterar: " + b.previousElementSibling?.textContent); PASSOS[b.dataset.passo](); });
    anexar(c);
    doca({textoLivre:false, botoes:[{rotulo:"Cotar agora →", primaria:true, acao:cotar}]});
  }
};

