  if (pais.iso === "BR") { entrada.placeholder = "Número, com DDD"; ajuda.textContent = "Ex.: (11) [REDIGIDO]8"; }
  else { entrada.placeholder = "Número de telefone, sem o código do país"; ajuda.textContent = `Só os números. O código +${pais.ddi} já está no país escolhido.`; }
};
paisSel.onchange = () => { atualizarMascara(); atualizarTextos(); };
atualizarMascara();
atualizarTextos();

